CREATE DATABASE IF NOT EXISTS trabajos_grado_uts CHARACTER SET utf8mb4; USE trabajos_grado_uts; CREATE TABLE usuario(id INT AUTO_INCREMENT PRIMARY KEY,documento VARCHAR(30) UNIQUE NOT NULL,nombre VARCHAR(150) NOT NULL,correo VARCHAR(150) UNIQUE NOT NULL,password_sha256 CHAR(64) NOT NULL,rol ENUM('ESTUDIANTE','DIRECTOR','EVALUADOR','COMITE','ADMINISTRADOR') NOT NULL,activo BOOLEAN DEFAULT TRUE,creado_en TIMESTAMP DEFAULT CURRENT_TIMESTAMP); CREATE TABLE proyecto(id INT AUTO_INCREMENT PRIMARY KEY,codigo VARCHAR(20) UNIQUE NOT NULL,titulo VARCHAR(180) NOT NULL,modalidad VARCHAR(60) NOT NULL,estado VARCHAR(40) NOT NULL,etapa TINYINT NOT NULL,creado_por INT NOT NULL,FOREIGN KEY(creado_por) REFERENCES usuario(id)); CREATE TABLE documento(id INT AUTO_INCREMENT PRIMARY KEY,proyecto_id INT NOT NULL,tipo VARCHAR(40) NOT NULL,url VARCHAR(1000) NOT NULL,estado VARCHAR(30) DEFAULT 'PENDIENTE',observaciones TEXT,FOREIGN KEY(proyecto_id) REFERENCES proyecto(id)); CREATE TABLE pago(id INT AUTO_INCREMENT PRIMARY KEY,proyecto_id INT NOT NULL,tipo VARCHAR(60) NOT NULL,url VARCHAR(1000) NOT NULL,estado VARCHAR(30) DEFAULT 'PENDIENTE',observaciones TEXT,FOREIGN KEY(proyecto_id) REFERENCES proyecto(id)); CREATE TABLE historial(id BIGINT AUTO_INCREMENT PRIMARY KEY,usuario_id INT,entidad VARCHAR(40) NOT NULL,entidad_id INT NOT NULL,accion VARCHAR(80) NOT NULL,observaciones TEXT,creado_en TIMESTAMP DEFAULT CURRENT_TIMESTAMP); INSERT INTO usuario(documento,nombre,correo,password_sha256,rol) VALUES('1000000000','Administrador UTS','admin@uts.edu.co',SHA2('CambiarEstaClave',256),'ADMINISTRADOR');